def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    queue = [(0, 0, 0)]
    visited = set()
    while queue:
        x, y, dist = queue.pop(0)
        if (x, y) in visited:
            continue
        visited.add((x, y))
        if grid[x][y] == 'E':
            return dist
        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] != 'W':
                queue.append((nx, ny, dist + 1))
    return -1

