def find_bridges(n: int, edges: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """
    এই ফাংশনটি প্রদত্ত edges এর মাধ্যমে সব সম্ভাব্য ট্র্যাভার্সাল খুঁজে বের করে।
    এটি একটি ডিকশনারি ব্যবহার করে প্রতিটি ট্র্যাভার্সালকে ট্র্যাভার্সাল টুপলের সাথে সংযুক্ত করে।
    যদি ট্র্যাভার্সাল টুপলের মধ্যে কোনও ট্র্যাভার্সাল অন্য ট্র্যাভার্সাল টুপলের সাথে সংযুক্ত না হয়, তবে সেই ট্র্যাভার্সাল টুপলটি ট্র্যাভার্সাল টুপলের তালিকায় যোগ করা হয়।
    এই ফাংশনটি সব সম্ভাব্য ট্র্যাভার্সাল খুঁজে বের করে, যা প্রদত্ত edges এর মাধ্যমে তৈরি হয়।
    """
    graph = {}
    for u, v in edges:
        if u not in graph:
            graph[u] = []
        if v not in graph:
            graph[v] = []
        graph[u].append(v)
        graph[v].append(u)
    bridges = []
    for u in graph:
        for v in graph[u]:
            if u != v and (u, v) not in bridges and (v, u) not in bridges:
                bridges.append((u, v))
    return bridges

