def get_users_by_ids(conn: sqlite3.Connection, ids: list[str]) -> list[tuple[int, str]]:
    cursor = conn.cursor()
    query = "SELECT id, username FROM users WHERE id IN ({})".format(','.join('?' for _ in ids))
