def sparse_vector_dot(v1: dict[int, float], v2: dict[int, float]) -> float:
    """
    এই ফাংশনটি দুটি sparse ভেক্টর `v1` এবং `v2` এর ডট প্রোডাক্ট হিসাব করে, যেখানে প্রতিটি সূচককে তার মান অনুযায়ী একটি ডিকশনারিতে সংযুক্ত করা হয়েছে; যদি কোনও সূচক ডিকশনারিতে না থাকে, তবে তার মান শূন্য।
    ডট প্রোডাক্টের ফলাফল একটি দশমিক সংখ্যা (float) যা 3 দশমিক স্থানে রাউন্ড করা হয়।
    """
    dot_product = 0.0
    for key in v1:
        if key in v2:
            dot_product += v1[key] * v2[key]
    return round(dot_product, 3)

