    """
    একটি র্যান্ডম স্ট্রিং ফেরত দিন যার দৈর্ঘ্য নির্দিষ্ট `length`।
    প্রতিটি অক্ষর র্যান্ডমভাবে 62টি সম্ভাব্য অক্ষর (ছোট হাতের অক্ষর `a-z`, বড় হাতের অক্ষর `A-Z`, এবং সংখ্যা `0-9`) থেকে নির্বাচিত হবে।
    যদি প্রদত্ত `length` 1 এর কম হয়, তবে ফাংশনটি একটি `ValueError` উত্থাপন করবে।
    """
    if length < 1:
        raise ValueError("প্রদত্ত `length` অবশ্যই 1 এর বেশি হতে হবে।")
    return ''.join(random.choice(62) for _ in range(length))

