def height_queue_reconstruction(people: list[list[int]]) -> list[list[int]]:
    """
    এই ফাংশনটি একটি তালিকা `people` ইনপুট হিসেবে নেয়, যেখানে প্রতিটি উপাদান একটি তালিকা `[h, k]`। এখানে, `h` একটি ব্যক্তির উচ্চতা, এবং `k` হলো এই ব্যক্তির সামনে থাকা ব্যক্তিদের মধ্যে উচ্চতার সমান বা তার চেয়ে বেশি। এই ফাংশনটি `people` এর উপাদানগুলো এমনভাবে সাজাবে যাতে প্রতিটি ব্যক্তি তাদের `k` মান সঠিক হয়। ইনপুটটি সর্বদা ধারাবাহিক হবে, অর্থাৎ সবসময় একটি বৈধ কুইন থাকবে; যদি `people` খালি হয়, তবে এটি একটি খালি তালিকা ফেরত দেবে।
    """
    height_queue = []
    for person in people:
        h = person[0]
        k = 0
        for i in range(1, len(person)):
            if person[i] == person[i-1] or person[i] > person[i-1]:
                k += 1
        height_queue.append([h, k])
    return height_queue

