def min_coins_bounded(coins: list[int], limits: list[int], target: int) -> int:
    if target == 0:
        return 0

    if len(coins) == 0:
        return -1

    if target < 0:
        return -1

    if target > sum(coins):
        return -1

    if target <= 0:
        return 0

    dp = [float('inf')] * (target + 1)
    dp[0] = 0

    for coin in coins:
        for i in range(coin, target + 1):
            for j in range(1, limits[i - coin - 1] + 1):
                dp[i] = min(dp[i], dp[i - coin] + j)

    return dp[target] if dp[target] != float('inf') else -1

