def decode_runs(encoded: str) -> str:
    decoded = []
    i = 0
    while i < len(encoded):
        char = encoded[i]
        if char == '\\':
            i += 1
            if i < len(encoded):
                decoded.append(char + encoded[i])
                i += 1
        elif char != '~':
            decoded.append(char)
            i += 1
        else:
            count_start = i + 1
            while i < len(encoded) and encoded[i].isdigit():
                i += 1
            count = int(encoded[count_start:i])
            if count > 0:
                decoded.append(char * count)
            else:
                decoded.append('')
            i += 1
    return ''.join(decoded)
