def shortest_path_one_break(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = -1, -1
    end_row, end_col = -1, -1

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == '#':
                start_row, start_col = i, j
            elif grid[i][j] == '.':
                end_row, end_col = i, j

    if start_row == -1 and end_row == -1:
        return -1

    queue = [(start_row, start_col, 0)]
    visited = set()

    while queue:
        row, col, moves = queue.pop(0)

        if row == end_row and col == end_col:
            return moves

        visited.add((row, col))

        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            new_row, new_col = row + dr, col + dc

            if 0 <= new_row < rows and 0 <= new_col < cols and grid[new_row][new_col] == '.' and (new_row, new_col) not in visited:
                queue.append((new_row, new_col, moves + 1))

    return -1

