def solve_congruences(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    """
    এই ফাংশনটি একটি সমতা ব্যবস্থা সমাধান করে, যেখানে প্রতিটি tuple (r, m) মানে যে সমীকরণটি x অবশ্যই পূরণ করতে হবে
    (x % m == r % m), যেখানে m একটি ধনাত্মক পূর্ণসংখ্যা; remainder r
    (r < m) বা r > m, এবং মডিউলের জোড়াগুলি জোড়া নয়; যদি সিস্টেমের একটি সমাধান থাকে, তবে এটি একটি tuple (x, L) ফেরত দেয়
    যেখানে L হলো সব মডিউলের লিনিয়ার গুণফল এবং x হলো অনন্য সমাধান যা 0 <= x < L; যদি সিস্টেমের কোনও সমাধান না থাকে, তবে এটি None ফেরত দেয়।
    একটি খালি তালিকা হলে, এটি (0, 1) ফেরত দেয়।
    """
    if len(congruences) == 0:
        return (0, 1)
    if len(congruences) == 1:
        return (congruences[0][0], congruences[0][1])
    if len(congruences) == 2:
        a, b = congruences[0]
        c, d = congruences[1]
        if a % d == 0 and b % d == 0:
            return (a, b)
        if a % d == 0 and b % d == 1:
            return (a, b)
        if a % d == 1 and b % d == 0:
            return (a, b)
        return None
    if len(congruences) == 3:
        a, b, c = congruences[0]
        d, e, f = congruences[1]
        if a % d == 0 and b % d == 0 and c % d == 0 and e % d == 0 and f % d == 0:
            return (a, b, c)
        if a % d == 0 and b % d == 1 and c % d == 0 and e % d == 0 and f % d == 1:
            return (a, b, c)
        if a % d == 1 and b % d == 0 and c % d == 0 and e % d == 1 and f % d == 0:
            return (a, b, c)
        return None
    return None

