def format_table(rows: list[list[str]], aligns: str) -> str:
    if not rows:
        return ""

    num_columns = len(rows[0])
    column_widths = [max(len(cell) for cell in column) for column in zip(*rows)]

    formatted_rows = []
    for row, alignment in zip(rows, aligns):
        formatted_cells = []
        for cell, width, align in zip(row, column_widths, alignment):
            padding = " " * (width - len(cell))
            if align == "l":
                formatted_cell = f"{cell}{padding}"
            elif align == "r":
                formatted_cell = f"{padding}{cell}"
            elif align == "c":
                left_padding = padding // 2
                right_padding = padding - left_padding
                formatted_cell = f"{left_padding}{cell}{right_padding}"
            formatted_cells.append(formatted_cell)
        formatted_rows.append(" | ".join(formatted_cells))

    return "\n".join(formatted_rows)
