def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    n = len(matrix)
    if n == 0:
        return []

    # outer ring
    outer_ring = []
    for i in range(n):
        outer_ring.append(matrix[i][n-1])

    # inner rings
    for i in range(1, n):
        inner_ring = []
        for j in range(n-1, -1, -1):
            inner_ring.append(matrix[j][i])
        outer_ring.extend(inner_ring)

    # central element
    if k > 0:
        outer_ring.append(matrix[n-1][n-1])
        outer_ring.append(matrix[n-1][n-1])
        outer_ring.append(matrix[n-1][n-1])

    # rotate
    for i in range(n):
        for j in range(n-1, -1, -1):
            matrix[i][j] = outer_ring[k+j]

    return matrix

