def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    board = [[0] * n for _ in range(n)]

    for row, col in blocked:
        board[row][col] = 1

    def is_safe(row, col, board):
        for r, c in board:
            if r == row or c == col or abs(r - row) == abs(c - col) or abs(r - row) == abs(c - col) + 1:
                return False
        return True

    def solve(board, row, col, num_queens):
        if row == n:
            return 1

        if not is_safe(row, col, board):
            return 0

        if num_queens == n:
            return 1

        count = 0
        for r in range(n):
            for c in range(n):
                if not is_safe(r, c, board) or board[r][c] == 1:
                    continue
                board[r][c] = 1
                count += solve(board, r, c + 1, num_queens + 1)
                board[r][c] = 0

        return count

    return solve(board, 0, 0, 0)

