import re

def is_allowed_webhook(url: str) -> bool:
    # Check if the URL starts with 'http://' or 'https://'
    if not url.startswith(('http://', 'https://')):
        return False

    # Check for any backslash, space, or control characters in the URL
    if re.search(r'[\x00-\x1F\x7F]', url):
        return False

    # Extract the host part of the URL
    host = url.split('//')[1].split('/')[0]

    # Split the host by '.' and check the conditions
    labels = host.split('.')
    if len(labels[-1]) == 0 or not labels[-1].isalpha():
        return False
    for label in labels[:-1]:
        if len(label) == 0 or not re.match(r'^[a-zA-Z0-9-]+$', label):
            return False

    # Check if the host is 'localhost' or ends with '.localhost'
    if host == 'localhost' or host.endswith('.localhost'):
        return False

    # Check if the port is present and not equal to 443
    if ':' in host:
        port = host.split(':')[1]
        if port != '443':
            return False

    return True
