def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    cache = {}
    results = []
    keys = []

    for op in operations:
        key, value = op
        if key in cache:
            cache[key] = value
            keys.append(key)
            keys.sort()
        else:
            cache[key] = value
            keys.append(key)

    if len(cache) < capacity:
        return (cache, keys)
    else:
        keys = sorted(keys, key=lambda x: cache.get(x, -float('inf')))

        for key in keys:
            if key in cache:
                cache[key] = value
                keys.remove(key)
                results.append(cache[key])
            else:
                results.append(None)
                cache[key] = value
                keys.append(key)

