def simulate_lru(capacity: int, operations: list[tuple]) -> tuple[list, list]:
    """
    একটি LRU (Least Recently Used) ক্যাশ সিমুলেট করুন যা সর্বোচ্চ `capacity` এ প্রবেশ করতে পারে।
    """
    cache = {}
    key_map = {}
    key_map[None] = None
    key_map[0] = None
    for op in operations:
        key, value = op
        if key in cache:
            cache[key] = value
            key_map[key] = None
        else:
            cache[key] = value
            key_map[key] = None
        if len(cache) >= capacity:
            key_map[cache[0]] = None
            key_map[cache[1]] = None
            cache = cache[1]
            key_map[cache[0]] = None
            key_map[cache[1]] = None
    return (key_map, operations)

