    আউটপুট:
    """
    stock = {}
    waiting = []
    for event in events:
        kind, item, quantity = event
        if kind == 'receive':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity
        elif kind == 'order':
            if item in stock:
                stock[item] += quantity
            else:
                stock[item] = quantity
            if item in waiting:
                waiting.append((item, quantity))
                waiting.sort(key=lambda x: x[1])
                if stock[item] >= quantity:
                    stock[item] -= quantity
                    waiting.remove((item, quantity))
                else:
                    waiting.append((item, quantity))
                    waiting.sort(key=lambda x: x[1])
        else:
            raise ValueError("অপ্রত্যাশিত ইনভেন্টরি টাইপ")
    return (stock, waiting)

